import React, { useEffect, useMemo, useState } from 'react';
import { useParams } from 'react-router-dom';
import { getCategoryProducts } from '../services/api';

export default function CategoryPage() {
  const { id } = useParams();
  const [cat, setCat] = useState(null);
  const [items, setItems] = useState([]);
  const [q, setQ] = useState('');

  // Carga productos de la categoría
  useEffect(() => {
    (async () => {
      const prods = await getCategoryProducts(id);
      setItems(prods || []);
    })();
  }, [id]);

  // Carga metadatos de la categoría (usa /api/categories y filtra por id)
  useEffect(() => {
    (async () => {
      try {
        const res = await fetch('/api/categories');
        const all = await res.json();
        const c = (all || []).find(x => String(x.id) === String(id));
        setCat(c || null);
      } catch {
        setCat(null);
      }
    })();
  }, [id]);

  const filtered = useMemo(() => {
    const term = q.trim().toLowerCase();
    if (!term) return items;
    return items.filter(p =>
      String(p.name || '').toLowerCase().includes(term) ||
      String(p.description || '').toLowerCase().includes(term)
    );
  }, [items, q]);

  const priceFmt = (n) =>
    typeof n === 'number' ? n.toLocaleString('es-AR') : '';

  const onSearchSubmit = (e) => {
    e.preventDefault();
    // ya filtramos en vivo; mantener submit inofensivo
  };

  const banner = cat?.imageBanner || cat?.imageUrl || ''; // fallback suave

  return (
    <div className="cp-cat">
      {/* Banner */}
      <section
        className="hero"
        style={banner ? { backgroundImage: `url(${banner})` } : {}}
        aria-label={cat?.name || `Categoría #${id}`}
      >
        <div className="hero-layer">
          <img
            className="logo"
            src="/logo.png"
            alt="Conecta Pinamar"
          />
          <h1 className="title">{(cat?.name || 'Categoría').toUpperCase()}</h1>

          <form className="search" onSubmit={onSearchSubmit}>
            <input
              type="search"
              placeholder="Buscar ofertas, productos, comercios y más"
              value={q}
              onChange={(e) => setQ(e.target.value)}
              aria-label="Buscar en la categoría"
            />
            <button type="submit" title="Buscar" aria-label="Buscar">
              <svg width="18" height="18" viewBox="0 0 24 24" aria-hidden="true">
                <path d="M21 21l-4.35-4.35m1.35-5.65a7 7 0 11-14 0 7 7 0 0114 0z" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
              </svg>
            </button>
          </form>
        </div>
      </section>

      {/* Grilla de productos */}
      <div className="grid">
        {filtered.map(p => (
          <a key={p.id} className="card" href={`/producto/${p.id}`}>
            <div className="thumb">
              <img src={p.imageUrl} alt={p.name} loading="lazy" />
            </div>
            <div className="meta">
              <div className="name">{p.name || 'producto'}</div>
              <div className="price">{typeof p.price !== 'undefined' ? `$ ${priceFmt(p.price)}` : '$'}</div>
            </div>
          </a>
        ))}
        {filtered.length === 0 && (
          <div className="empty">Sin resultados para “{q}”.</div>
        )}
      </div>

      {/* estilos en el mismo archivo */}
      <style>{`
        .cp-cat{ --yellow:#F7D34A; --ink:#111; --card:#fff; --border:#e6e6e6; --shadow:0 8px 24px rgba(0,0,0,.08); }

        /* HERO */
        .hero{
          position:relative;
          width:100%;
          min-height:220px;
          background:#ddd center/cover no-repeat;
          display:grid;
          place-items:center;
          padding:24px 16px 64px;
        }
        .hero::after{
          content:"";
          position:absolute; inset:0;
          background:linear-gradient(180deg, rgba(0,0,0,.25), rgba(0,0,0,.35));
        }
        .hero-layer{
          position:relative; z-index:1;
          width:100%; max-width:1100px;
          display:flex; flex-direction:column; align-items:center; gap:14px;
        }
        .logo{
          background-color: var(--cp-yellow), 0.5;
          height:72px;
          display:block;
          margin:0 auto;
          filter:drop-shadow(0 1px 0 rgba(0,0,0,.25));
        }
        .title{
          margin:0;
          font: 800 30px/1.05 system-ui,-apple-system,Segoe UI,Roboto,Ubuntu,Cantarell,Noto Sans,sans-serif;
          letter-spacing:.5px;
          color:#fff;
          text-align:center;
          text-shadow:0 2px 8px rgba(0,0,0,.35);
        }

        /* BUSCADOR */
        .search{
          margin-top:6px;
          display:flex; align-items:center;
          gap:0; width:100%; max-width:640px;
          background:#fff; border:2px solid var(--yellow);
          border-radius:999px; padding:6px; box-shadow:0 4px 18px rgba(0,0,0,.1);
        }
        .search input{
          flex:1; border:0; outline:none;
          font-size:14px; padding:8px 12px; background:transparent;
        }
        .search button{
          display:grid; place-items:center;
          border:0; outline:none; cursor:pointer;
          background:var(--yellow); color:#000;
          border-radius:999px; width:38px; height:38px;
          transition:transform .08s ease, box-shadow .15s ease, opacity .15s ease;
        }
        .search button:hover{ transform:translateY(-1px); box-shadow:0 6px 14px rgba(0,0,0,.18); }
        .search button:active{ transform:translateY(0); box-shadow:none; }

        /* GRID */
        .grid{
          max-width:1100px; margin:24px auto;
          padding:0 16px 32px;
          display:grid;
          grid-template-columns:repeat(auto-fill, minmax(180px, 1fr));
          gap:18px;
        }
        .card{
          display:flex; flex-direction:column;
          background:var(--card);
          border:1px solid var(--border);
          border-radius:16px;
          text-decoration:none; color:#111;
          box-shadow:var(--shadow);
          transition:transform .12s ease, box-shadow .12s ease;
        }
        .card:hover{ transform:translateY(-2px); box-shadow:0 10px 26px rgba(0,0,0,.12); }
        .thumb{ aspect-ratio: 1 / 1; width:100%; overflow:hidden; border-top-left-radius:16px; border-top-right-radius:16px; }
        .thumb img{ width:100%; height:100%; object-fit:cover; display:block; }
        .meta{ padding:10px 12px 12px; }
        .name{
          font-weight:800; font-size:18px; line-height:1.1; margin:0 0 6px 0;
        }
        .price{
          font-weight:900; font-size:20px;
        }
        .empty{
          grid-column:1 / -1;
          text-align:center; color:#666; padding:24px 0;
        }

        /* Desktop tweaks */
        @media (min-width: 900px){
          .hero{ min-height:300px; padding:36px 16px 90px; }
          .title{ font-size:40px; }
          .grid{ gap:22px; }
          .name{ font-size:20px; }
          .price{ font-size:22px; }
        }
      `}</style>
    </div>
  );
}
